/* tokens/base.css */
@media (pointer: coarse) {
  /* !important on purpose: component styles set 13-14px on fields; iOS checks the computed size */
  input, textarea, select, [contenteditable] { font-size: 16px !important; }
}

html {
  -webkit-text-size-adjust: 100%;  /* iOS Safari needs the prefix */
  text-size-adjust: 100%;          /* Chromium */
}

.hero     { min-height: 100vh; min-height: 100svh; }  /* fully visible on first paint, never jumps */
.sheet    { max-height: 90vh;  max-height: 90svh; }   /* bottom sheets/modals always fit */
.bg-layer { position: fixed; inset: 0; }              /* or height: 100lvh; never exposes a gap as bars retract */
.shell    { height: 100vh;     height: 100dvh; }      /* tracks the bars; for shells whose document doesn't scroll */

/* In a locked shell, a plain 100% chain is equivalent and survives iOS standalone quirks: */
html { height: 100%; } body, #root { height: 100%; }

:root {
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
}
.topbar { padding-top: max(12px, var(--safe-top)); }        /* background bleeds, content inset */
.tabbar { padding-bottom: max(8px, var(--safe-bottom)); }
.row    { padding-left: max(16px, var(--safe-left)); padding-right: max(16px, var(--safe-right)); } /* landscape notch */
.fab    { position: fixed; right: calc(16px + var(--safe-right)); bottom: calc(16px + var(--safe-bottom)); }
/* inside a container that already pads --safe-bottom: don't double-pad */
.composer { padding-bottom: max(0px, 10px - var(--safe-bottom)); }

.bottom-cta {
  position: fixed; left: 0; right: 0; bottom: 0;
  /* constant reserve in Chromium; dynamic inset (or 0) elsewhere */
  padding-bottom: calc(12px + env(safe-area-max-inset-bottom, env(safe-area-inset-bottom, 0px)));
}

/** Recommended setup: Android → interactive-widget=resizes-content (layout fits, no JS);
 *  iOS → visualViewport-driven shell (next item); bottom UI in-flow, never position:fixed. */
const KEYBOARD_MIN = 120; // taller than any browser bar that comes and goes, shorter than any keyboard

/** True while something (a keyboard) covers the bottom of a layout that did NOT resize for it. */
export function keyboardCoversLayout(): boolean {
  const vv = window.visualViewport;
  return vv !== null && document.documentElement.clientHeight - vv.height * vv.scale > KEYBOARD_MIN;
}

const KEYBOARD_MIN = 120;
type Visible = { height: number; scale: number; pageTop: number };

/** Pure, unit-testable. */
export function viewportVars(layoutHeight: number, vv: Visible): Record<string, string | null> {
  const height = vv.height * vv.scale; // x scale: pinch-zoom must not shrink the app
  if (layoutHeight - height < KEYBOARD_MIN) return { '--app-height': null, '--app-top': null, '--safe-bottom': null };
  // don't follow the pan while zoomed: the user is panning, not iOS
  return { '--app-height': `${height}px`, '--app-top': `${vv.scale === 1 ? vv.pageTop : 0}px`, '--safe-bottom': '0px' };
}

export function trackViewport(): () => void {
  const vv = window.visualViewport;
  if (vv === null) return () => {};
  const root = document.documentElement;
  const update = () => {
    for (const [name, value] of Object.entries(viewportVars(root.clientHeight, vv))) {
      if (value === null) root.style.removeProperty(name);
      else root.style.setProperty(name, value);
    }
  };
  vv.addEventListener('resize', update);
  vv.addEventListener('scroll', update);
  update();
  return () => { vv.removeEventListener('resize', update); vv.removeEventListener('scroll', update); };
}

/* CSS */
html { height: 100%; }
body { height: var(--app-height, 100%); margin: 0; overflow: hidden; overscroll-behavior: none;
       transform: translateY(var(--app-top, 0px)); } /* a transform, so fixed overlays move with the app */
/* tests: viewportVars(844,{height:508,scale:1,pageTop:336}) → 508px / 336px / 0px;
          viewportVars(844,{height:797,scale:1,pageTop:0}) → all null (standalone status-bar case) */

/* Best: no fixed bottom UI; in-flow rows in a locked shell sized by the visualViewport item. */

// If a document-scroll page must keep a fixed bottom bar, lift it above the visual viewport bottom:
const vv = window.visualViewport;
const bar = document.querySelector<HTMLElement>('.fixed-bottom');
if (vv && bar) {
  const place = () => {
    const hidden = window.innerHeight - (vv.offsetTop + vv.height); // layout px below the visible area
    bar.style.transform = `translateY(${-Math.max(0, hidden)}px)`;
  };
  vv.addEventListener('resize', place);
  vv.addEventListener('scroll', place);
  place();
}
// iOS sometimes leaves a locked page panned after the keyboard closes:
document.addEventListener('focusout', () => requestAnimationFrame(() => { if (window.scrollY !== 0) window.scrollTo(0, 0); }));

// in a module file
interface VirtualKeyboardLike extends EventTarget {
  overlaysContent: boolean;
  readonly boundingRect: DOMRect;
  show(): void;
  hide(): void;
}
declare global { interface Navigator { readonly virtualKeyboard?: VirtualKeyboardLike } }
export {};

const vk = navigator.virtualKeyboard;
if (vk) {
  vk.overlaysContent = true; // viewport no longer resizes; keyboard-inset-* become non-zero
  vk.addEventListener('geometrychange', () => {
    document.documentElement.toggleAttribute('data-keyboard', vk.boundingRect.height > 0);
  });
}

/* CSS */
.app { grid-template-rows: auto minmax(0, 1fr) auto env(keyboard-inset-height, 0px); }
.scroller { scroll-padding-bottom: env(keyboard-inset-height, 0px); }

<!-- HTML: keyboard only when you call vk.show() -->
<div contenteditable virtualkeyboardpolicy="manual"></div>

declare global { interface ScrollIntoViewOptions { container?: 'all' | 'nearest' } } // Chromium 140+
export {};

/** Scrolls `scroller` only; never the document. */
export function reveal(el: Element, scroller: HTMLElement, pad = 12): void {
  const e = el.getBoundingClientRect();
  const s = scroller.getBoundingClientRect();
  if (e.top < s.top + pad) scroller.scrollTop -= s.top + pad - e.top;
  else if (e.bottom > s.bottom - pad) scroller.scrollTop += e.bottom - (s.bottom - pad);
}

window.visualViewport?.addEventListener('resize', () => {
  const el = document.activeElement;
  const scroller = el?.closest<HTMLElement>('[data-scroll-root]');
  if (el && scroller && el.matches('input, textarea, select, [contenteditable]')) reveal(el, scroller);
});

// programmatic focus (roving tabindex, 'reply' button) without page jumps
field.focus({ preventScroll: true });
reveal(field, scroller);
// Chromium-only declarative form: el.scrollIntoView({ block: 'nearest', container: 'nearest' });

/* CSS */
.scroller { scroll-padding-top: var(--sticky-h, 0px); scroll-padding-bottom: 16px; }

.composer textarea {
  field-sizing: content;     /* size to content */
  min-block-size: 2.75rem;
  max-block-size: 8lh;       /* then scroll; lh avoids vh, which ignores the iOS keyboard */
  overflow-y: auto;
  resize: none;
}

// fallback for older engines
if (!CSS.supports('field-sizing', 'content')) {
  textarea.addEventListener('input', () => {
    textarea.style.height = 'auto';
    textarea.style.height = `${Math.min(textarea.scrollHeight, 200)}px`;
  });
}

.feed { overflow-anchor: auto; }                       /* default */
.feed .loading-row, .feed .typing { overflow-anchor: none; } /* never anchor on transient rows */

// Fallback for Safari < 27 when prepending history. Only when unsupported, or you'll correct twice.
export function prependKeepingPosition(scroller: HTMLElement, prepend: () => void): void {
  if (CSS.supports('overflow-anchor', 'auto')) { prepend(); return; }
  const fromBottom = scroller.scrollHeight - scroller.scrollTop;
  prepend(); // synchronous DOM update (useLayoutEffect / flushSync in React)
  scroller.scrollTop = scroller.scrollHeight - fromBottom;
}

/* delete */
.scroller { -webkit-overflow-scrolling: touch; }  /* momentum is the default since iOS 13 */
.full { height: -webkit-fill-available; }
/* use */
.scroller { overflow-y: auto; overscroll-behavior: contain; }
.full { height: 100svh; }               /* or a 100% chain in a locked shell */

// delete: window.addEventListener('orientationchange', …) and document.addEventListener('touchmove', e => e.preventDefault(), { passive: false })
// use: screen.orientation 'change' / matchMedia, and overscroll-behavior + a locked shell

.pager {
  display: grid; grid-auto-flow: column; grid-auto-columns: 100%;
  overflow-x: auto; scroll-snap-type: x mandatory;
  overscroll-behavior-x: contain; scrollbar-width: none;
}
.pager > section { scroll-snap-align: start; scroll-snap-stop: always; } /* one page per swipe */

const pager = document.querySelector<HTMLElement>('.pager');
if (pager) {
  const current = () => Math.round(Math.abs(pager.scrollLeft) / pager.clientWidth); // abs: RTL scrollLeft is negative
  if ('onscrollend' in window) pager.addEventListener('scrollend', () => setPage(current()));
  else {
    let t = 0;
    pager.addEventListener('scroll', () => { clearTimeout(t); t = window.setTimeout(() => setPage(current()), 120); }, { passive: true });
  }
}
const goTo = (el: HTMLElement, i: number) => el.scrollTo({ left: i * el.clientWidth, behavior: 'smooth' });

.page { overflow-x: clip; }            /* clips without becoming a scroll container: sticky descendants keep working */
.row > * { min-width: 0; }             /* flex/grid items default to min-width:auto and refuse to shrink */
.message-text { overflow-wrap: anywhere; }
img, video { max-width: 100%; height: auto; }
.full-bleed { width: 100%; }           /* not 100vw: on desktop 100vw includes the scrollbar → horizontal overflow */

.scroller { scroll-padding-top: var(--section-header-h, 40px); }
.section-header { position: sticky; top: 0; z-index: 1; container-type: scroll-state; }
.section-header > .bar { background: var(--surface-page); transition: box-shadow .2s; }
@container scroll-state(stuck: top) {
  .section-header > .bar { box-shadow: 0 1px 0 var(--border-subtle); } /* the query styles descendants, not the container */
}

/* Chromium 115+, Safari 26+: tint/separate the bar as you scroll the first 96px */
@supports (animation-timeline: scroll()) {
  .topbar { animation: settle linear both; animation-timeline: scroll(nearest block); animation-range: 0 96px; }
  @keyframes settle { to { background-color: var(--surface-bar); box-shadow: 0 1px 0 var(--border-subtle); } }
}
/* Chromium 144+: hide while scrolling down, show on scroll up */
.scroller { container: main / scroll-state; }
.topbar { position: sticky; top: 0; transition: translate .2s; }
@container main scroll-state(scrolled: bottom) { .topbar { translate: 0 -100%; } }
@media (prefers-reduced-motion: reduce) { .topbar { transition: none; } }

const saved = new Map<string, number>();
const scrollRoot = () => document.querySelector<HTMLElement>('[data-scroll-root]');

navigation.addEventListener('navigate', (e) => {
  if (!e.canIntercept || e.hashChange || e.downloadRequest !== null) return;
  const from = navigation.currentEntry;
  const el = scrollRoot();
  if (from && el) saved.set(from.key, el.scrollTop);
  e.intercept({
    scroll: 'manual',
    async handler() {
      await renderRoute(new URL(e.destination.url)); // your router
      const key = navigation.currentEntry?.key;     // now the destination entry
      const target = scrollRoot();
      if (target) target.scrollTop = e.navigationType === 'traverse' && key !== undefined ? (saved.get(key) ?? 0) : 0;
    },
  });
});

// History-API routers: stop the browser restoring the document before your view exists
history.scrollRestoration = 'manual';

const landscape = matchMedia('(orientation: landscape)');
landscape.addEventListener('change', (e) => setLandscape(e.matches));
screen.orientation.addEventListener('change', () => requestAnimationFrame(remeasure)); // sizes settle after the event

/* compact phone landscape: little height, hide secondary chrome */
@media (orientation: landscape) and (max-height: 500px) {
  .topbar .subtitle { display: none; }
  .tabbar { padding-block: 4px; }
}

async function lockLandscape(video: HTMLElement): Promise<void> {
  try { await video.requestFullscreen(); await screen.orientation.lock('landscape'); }
  catch { /* NotSupportedError on iOS, desktop; fine */ }
}

@media (horizontal-viewport-segments: 2) {
  .layout {
    display: grid;
    grid-template-columns:
      env(viewport-segment-width 0 0)
      calc(env(viewport-segment-left 1 0) - env(viewport-segment-right 0 0)) /* hinge */
      env(viewport-segment-width 1 0);
  }
  .list { grid-column: 1; } .detail { grid-column: 3; }
}
@media (vertical-viewport-segments: 2) { /* top/bottom halves (laptop posture): same idea with rows and viewport-segment-height/top/bottom */ }

declare global { interface Window { readonly viewport?: { readonly segments: ReadonlyArray<DOMRect> | null } } }
export {};
const spanned = () => (window.viewport?.segments?.length ?? 1) > 1;
addEventListener('resize', () => setDualPane(spanned()));

@media (device-posture: folded) and (orientation: landscape) {
  .player { display: grid; grid-template-rows: 1fr 1fr; } /* top: video, bottom: controls */
}

declare global {
  interface Navigator { readonly devicePosture?: EventTarget & { readonly type: 'continuous' | 'folded' } }
}
export {};
navigator.devicePosture?.addEventListener('change', () => setTabletop(navigator.devicePosture?.type === 'folded'));

.pane { container: pane / inline-size; }
@container pane (width >= 36rem) { .message { grid-template-columns: 3rem minmax(0, 1fr) auto; } }
@container pane (width < 36rem)  { .message .meta { display: none; } }
.card-title { font-size: clamp(1rem, 3.5cqi, 1.375rem); }

.layout { height: 100%; display: grid; grid-template-columns: minmax(0, 1fr); }
@media (width >= 768px) {
  .layout { grid-template-columns: clamp(260px, 30%, 360px) minmax(0, 1fr); }
  .detail-empty { display: grid; place-items: center; } /* never a blank right pane */
}
.reading { max-inline-size: 72ch; margin-inline: auto; } /* readable measure on desktop */

const wide = matchMedia('(width >= 768px)');
const openThread = (id: string) => (wide.matches ? selectInPlace(id) : pushRoute(`/t/${id}`));
wide.addEventListener('change', syncLayoutWithRoute);

