{ "display": "standalone", "display_override": ["window-controls-overlay"] }

.titlebar {
  position: fixed;
  left: env(titlebar-area-x, 0); top: env(titlebar-area-y, 0);
  width: env(titlebar-area-width, 100%); height: env(titlebar-area-height, 36px);
